class TreeNode {

    int val;
    TreeNode left;
    TreeNode right;

    TreeNode() {
    }

    TreeNode(int val) {
        this.val = val;
    }

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

@DisplayName("80/73_construct_binary_tree_from_inorder_and_postorder_traversal (incomplete)")
class SolutionIncompleteTest {

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldBuildTreeFromExampleOne() {

        Solution solution = new Solution();

        TreeNode root = solution.buildTree(
            new int[]{9, 3, 15, 20, 7},
            new int[]{9, 15, 7, 20, 3}
        );

        assertEquals(Arrays.asList(3, 9, 20, null, null, 15, 7), serialize(root));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldBuildSingleNodeTree() {

        Solution solution = new Solution();

        TreeNode root = solution.buildTree(new int[]{-1}, new int[]{-1});

        assertEquals(Arrays.asList(-1), serialize(root));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldBuildLeftSkewedTree() {

        Solution solution = new Solution();

        TreeNode root = solution.buildTree(
            new int[]{3, 2, 1},
            new int[]{3, 2, 1}
        );

        assertEquals(1, root.val);
        assertEquals(2, root.left.val);
        assertEquals(3, root.left.left.val);
        assertNull(root.right);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldBuildRightSkewedTree() {

        Solution solution = new Solution();

        TreeNode root = solution.buildTree(
            new int[]{1, 2, 3},
            new int[]{3, 2, 1}
        );

        assertEquals(1, root.val);
        assertEquals(2, root.right.val);
        assertEquals(3, root.right.right.val);
        assertNull(root.left);
    }

    private List<Integer> serialize(TreeNode root) {

        List<Integer> values = new ArrayList<>();

        if (root == null) {
            return values;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();

            if (node == null) {
                values.add(null);
                continue;
            }

            values.add(node.val);
            queue.offer(node.left);
            queue.offer(node.right);
        }

        int last = values.size() - 1;

        while (last >= 0 && values.get(last) == null) {
            last--;
        }

        return values.subList(0, last + 1);
    }
}

